{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 조례상 교통약자(장애·노령으로 자전거 이용이 어려운 사람)를 위한 장비·시설 확충 근거 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제3조 제3항은 시장이 노약자 등 교통약자가 자전거 이용에 있어서 차별이 발생하지 않도록 관련 장비와 시설을 확충할 수 있다고 정하고 있다. 따라서 장애나 나이 등으로 자전거 이용이 어려운 사람을 위한 장비·시설 보완을 제안하는 근거로 이 조항을 들 수 있다. 다만 이는 시장이 확충할 수 있다는 재량 규정이며, 구체적인 확충 대상·범위·방법은 조례에 직접 정해져 있지 않다.",
          "b_ids": "자전거:제3조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
